		logAtZapLevel(decoded.level, decoded.text)
	} else if s.detectLevelPrefixes {
		if matched, level := extractLevelPrefix(line); matched {
			logAtZapLevel(level, line)
		} else {
			logAtZapLevel(s.fallbackLevel, line)
		}
	} else {
		logAtZapLevel(s.fallbackLevel, line)
	}
