func (s *JSONLogStreamer) process(reader io.Reader) {
	defer close(s.done)
	scanner := bufio.NewScanner(reader)
	buf := make([]byte, 0, 64*1024)
	scanner.Buffer(buf, 1024*1024)

	for scanner.Scan() {
		line := s.redactor.Redact(scanner.Text())
		s.LogLine(line)
		s.capture(line)
	}
	if err := scanner.Err(); err != nil {
		Debugf("error reading subprocess output: %v", err)
	}
	if closer, ok := reader.(io.Closer); ok {
		_ = closer.Close()
	}
}

func (s *JSONLogStreamer) capture(line string) {
	if s.captureLines <= 0 && s.captureBytes <= 0 {
		return
	}
	if s.captureBytes > 0 && len(line) > s.captureBytes {
		line = line[len(line)-s.captureBytes:]
	return buildOptions, nil
}

func redactBuildSecrets(buildOptions *build.BuildOptions) build.BuildOptions {
	redacted := *buildOptions
	if len(buildOptions.BuildSecrets) == 0 {
		return redacted
	}
	names := make([]string, len(buildOptions.BuildSecrets))
	for i, entry := range buildOptions.BuildSecrets {
		name, _, _ := strings.Cut(entry, "=")
		names[i] = name + "=<redacted>"
	}
	redacted.BuildSecrets = names
	return redacted
}

func (d *dockerDriver) executeBuild(
	ctx context.Context,
	strategy buildStrategy,
	req driver.BuildRequest,
	buildOptions *build.BuildOptions,
) error {
	log.Debugf("build with %s", strategy.name())
	writer := log.NewJSONLogStreamer(log.StreamerOptions{
		FallbackLevel: log.LevelInfo,
	})
	defer func() { _ = writer.Close() }()

	if err := strategy.build(ctx, writer, req.Options.Platform, buildOptions); err != nil {
		return fmt.Errorf("%s build: %w", strategy.name(), err)
	}
	return nil
}

